	/**
	 * [MS_MSBCL0210_Srch01]の定型処理のInnerClass
	 */
	protected class MS_MSBCL0210_Srch01Bridge extends MCCallerPanelBridge {
		/**
		 * 電文パラメータ<p>
		 * 
		 * 参照する場合には{@link #param()}を使用してください。
		 */
		MCParam p_MS_MSBCL0210_Srch01;

		/** コンストラクタ */
		protected MS_MSBCL0210_Srch01Bridge() {
			p_MS_MSBCL0210_Srch01 = new MCParam(PDef.MS_MSBCL0210_Srch01_INFO);
		}

		@Override
		public MCParam createAsyncParam() {
			MCParam param = new MCParam(PDef.MS_MSBCL0210_Srch01_INFO);
			param.setReqSrcId(getScreenID());
			// Up
			param.addUpBlock(mcframe.clientMSBC.MSBCP0210.CndR.create());
			// Down
			param.addDownBlock(MCList.create(mcframe.clientMSBC.MSBCP0210.RsltR.class));

			p_MS_MSBCL0210_Srch01 = param;
			return param;
		}

		/** パラメータを通信用に設定します。*/
		protected void setupParam() {
			p_MS_MSBCL0210_Srch01.setReqSrcId(getScreenID());
			setupUpParam();
			setupDownParam();
		}

		protected void setupUpParam() {
			p_MS_MSBCL0210_Srch01.addUpBlock(getCndR());
		}

		protected MCContainer up(int i) {
			return p_MS_MSBCL0210_Srch01.getContainerParam().getUpBlock(i);
		}
		
		protected MCContainer down(int i) {
			return p_MS_MSBCL0210_Srch01.getContainerParam().getDownBlock(i);
		}
		
		protected mcframe.clientMSBC.MSBCP0210.CndR up0() {
			return (mcframe.clientMSBC.MSBCP0210.CndR)up(0);
		}

		protected MCList<mcframe.clientMSBC.MSBCP0210.RsltR> down0() {
			return (MCList<mcframe.clientMSBC.MSBCP0210.RsltR>)down(0);
		}

		protected void setupDownParam() {
			p_MS_MSBCL0210_Srch01.addDownBlock(MCList.create(mcframe.clientMSBC.MSBCP0210.RsltR.class));
		}
		protected MCParam param() {
			return p_MS_MSBCL0210_Srch01;
		}

		protected void show() {
			setRsltL((MCList<mcframe.clientMSBC.MSBCP0210.RsltR>)p_MS_MSBCL0210_Srch01.getContainerParam().getDownBlock(0));
		}

		protected void clear() {
			getRsltL().clear();
		}
		
		protected List<MCContainer> getUpBlocks() {
			List<MCContainer> result = new ArrayList<MCContainer>();
			result.add(getCndR());
			return result;
		}
		
		protected List<MCContainer> getDownBlocks() {
			List<MCContainer> result = new ArrayList<MCContainer>();
			result.add(getRsltL());
			return result;
		}
	}
